{"content": "from fastapi import FastAPI, APIRouter
from starlette.routing import BaseRoute

def test_iter_route_contexts():
    app = FastAPI()
    router = APIRouter()

    @router.get("/test")
    def test_route():
        return {"hello": "world"}

    app.include_router(router)

    contexts = list(app.iter_route_contexts())
    assert len(contexts) == 1
    route, context = contexts[0]
    assert isinstance(route, BaseRoute)
    assert context is not None
    assert context.path == "/test"

def test_nested_iter_route_contexts():
    app = FastAPI()
    parent_router = APIRouter()
    child_router = APIRouter()

    @child_router.get("/child")
    def child_route():
        return {"hello": "child"}

    parent_router.include_router(child_router, prefix="/parent")
    app.include_router(parent_router)

    contexts = list(app.iter_route_contexts())
    assert len(contexts) == 1
    route, context = contexts[0]
    assert context.path == "/parent/child"

if __name__ == "__main__":
    test_iter_route_contexts()
    test_nested_iter_route_contexts()
    print("All tests passed!")
